/// <summary>
/// Transfer order load planning report
/// </summary>
[SRSReportParameterAttribute(classstr(METTransferOrderLoadPlanningContract))]
class METTransferOrderLoadPlanningDP extends SrsReportDataProviderPreProcessTempDB
{
    METTransferOrderLoadPlanningLinesTmp transferOrderLoadPlanningLinesTmp;
    METTransferOrderLoadPlanningContract        contract;

}

Method.Source:
/// <summary>
/// Transfer order tmp table
/// </summary>
/// <returns>tmp table</returns>
[SRSReportDataSetAttribute(tablestr(METTransferOrderLoadPlanningLinesTmp))]
public METTransferOrderLoadPlanningLinesTmp getTransferOrder()
{
    select transferOrderLoadPlanningLinesTmp;
    return transferOrderLoadPlanningLinesTmp;
}

public void processReport()
{
    contract = this.parmDataContract() as METTransferOrderLoadPlanningContract;

    InventTransferShipDate confirmedShipDateFrom = contract.parmConfirmedShipDateFrom();
    InventTransferShipDate confirmedShipDateTo = contract.parmConfirmedShipDateTo();

    InventTransferTable         inventTransferTable;
    InventTransferLine          inventTransferLine;
    METInventTransferTableExt   metInventTransferTableExt;
    METInventTransferLine       metInventTransferLine;
    InventLocation              inventLocationFrom;
    InventLocation              inventLocationTo;
    METInventLocation           metInventLocation;
    RecordInsertList            transferOrderLoadPlanningAidLineslist = new RecordInsertList(tableNum(METTransferOrderLoadPlanningLinesTmp), false, false, false, false, false, transferOrderLoadPlanningLinesTmp);

    while select RecId, TransferId from inventTransferLine
        join ShipDate, RecId from inventTransferTable
            where inventTransferTable.TransferId == inventTransferLine.TransferId
            && inventTransferTable.TransferStatus == InventTransferStatus::Created
            && (inventTransferTable.ShipDate >= confirmedShipDateFrom && inventTransferTable.ShipDate <= confirmedShipDateTo)
        join BrokenCase, Cases, TotalVolume, TotalWeight  from metInventTransferLine
            where metInventTransferLine.InventTransferLine == inventTransferLine.RecId
        join Name from inventLocationFrom
            where inventLocationFrom.InventLocationId == inventTransferTable.InventLocationIdFrom
        join Name, RecId from inventLocationTo
            where inventLocationTo.InventLocationId == inventTransferTable.InventLocationIdTo
        join InternalCustomer from metInventLocation
            where metInventLocation.InventLocation == inventLocationTo.RecId
        join Route, RouteStopNum, StagingLane from metInventTransferTableExt
            where metInventTransferTableExt.InventTransferTable == inventTransferTable.RecId
    {
        transferOrderLoadPlanningLinesTmp.FromWareHouseName = inventLocationFrom.Name;
        transferOrderLoadPlanningLinesTmp.ToWareHouseName = inventLocationTo.Name;

        transferOrderLoadPlanningLinesTmp.Suburb = this.getWareHousePrimaryAddress(inventLocationTo.RecId).County;
        transferOrderLoadPlanningLinesTmp.ConfirmedShipDate = inventTransferTable.ShipDate;
        transferOrderLoadPlanningLinesTmp.Route = metInventTransferTableExt.Route;
        transferOrderLoadPlanningLinesTmp.RouteStop = metInventTransferTableExt.RouteStopNum;
        transferOrderLoadPlanningLinesTmp.StagingLane = metInventTransferTableExt.StagingLane;
        transferOrderLoadPlanningLinesTmp.BrokenCase = metInventTransferLine.BrokenCase;
        transferOrderLoadPlanningLinesTmp.Cases = metInventTransferLine.Cases;
        transferOrderLoadPlanningLinesTmp.TotalVolume = metInventTransferLine.TotalVolume;
        transferOrderLoadPlanningLinesTmp.TotalWeight = metInventTransferLine.TotalWeight;
        transferOrderLoadPlanningLinesTmp.InternalCustomer = metInventLocation.InternalCustomer;
        transferOrderLoadPlanningAidLineslist.add(transferOrderLoadPlanningLinesTmp);
    }

    transferOrderLoadPlanningAidLineslist.insertDatabase();

}

/// <summary>
/// Get WareHouse address By recevingdock role
/// </summary>
/// <param name = "_inventLocationRecId">Location RecId</param>
/// <returns>Locator</returns>
private LogisticsEntityPostalAddressView getWareHousePrimaryAddress(RefRecId _inventLocationRecId)
{
    LogisticsEntityPostalAddressView  logisticsEntityPostalAddressView;

    select firstonly Address from logisticsEntityPostalAddressView
        where logisticsEntityPostalAddressView.Entity == _inventLocationRecId
        && logisticsEntityPostalAddressView.EntityType == LogisticsLocationEntityType::Warehouse
        && logisticsEntityPostalAddressView.ValidFrom <= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.ValidTo >= DateTimeUtil::getSystemDateTime()
        && logisticsEntityPostalAddressView.IsPrimary == NoYes::Yes;

    return logisticsEntityPostalAddressView;
}
